ROLLOUT = {"new-checkout": 10}          # percent of users who see the new code

def is_on(flag, user_id):
    return user_id % 100 < ROLLOUT.get(flag, 0)

def checkout(user_id):
    return "new checkout" if is_on("new-checkout", user_id) else "old checkout"

print(checkout(7), "|", checkout(42))   # new checkout | old checkout
